local UIMainChapterQuestNode = Class("UIMainChapterQuestNode")
function UIMainChapterQuestNode:__init()
    self._curQuestVo = nil
    self._cb = nil
    self._isUnlockId = false
end

function UIMainChapterQuestNode:__delete()
    self._curQuestVo = nil
    self._cb = nil
    self._isUnlockId = false
end

function UIMainChapterQuestNode:Awake()
end

function UIMainChapterQuestNode:Start()
    SetButtonAction(self.BtnBubbleGroup, Bind(self, self.OnBtnQuest))
end

function UIMainChapterQuestNode:Refresh(questId, cb, isUnlockId)
    self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not self._curQuestVo then
        return
    end
    if cb then
        self._cb = cb
    end 
    local levelType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    self._isChallenge = checkBool(levelType == Constants.IDType.QuestMainChallenge)
    self._curQuestId = checkNumber(questId)
    self._isUnlockId = checkBool(isUnlockId)

    self:FillSelf()
end

function UIMainChapterQuestNode:FillSelf()
    self:FillOther(false)

    CfUtils.FillText(self.TxtCheckpoint, self._curQuestVo.label)
    CfUtils.SetActive(self.Item1, false)
    CfUtils.SetActive(self.Item2, false)
    CfUtils.SetActive(self.SmallNormal.transform:Find("Item3"), false)
    CfUtils.SetActive(self.SmallNormal.transform:Find("Item3/ImgFight"), false)
    CfUtils.SetActive(self.Item1.transform:Find("Mask/ImgRole"), false)
    CfUtils.SetActive(self.Item1.transform:Find("Mask/ImgMonster"), false)
    CfUtils.SetActive(self.ImgRole, false)
    CfUtils.SetActive(self.ImgMonster, false)

    local isUnlock 
    local isPass

    if self._isChallenge then
        isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._curQuestId)
        isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curQuestId)
    else
        isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._curQuestId)
        isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curQuestId)
    end
    if self._isUnlockId then
        isUnlock = false
        isPass = false
    end
    --CfUtils.SetActive(self.TxtCheckpoint, isUnlock)
    CfUtils.SetActive(self.Item1.transform:Find("Mask/FinishBlack"), isPass or not isUnlock)
    CfUtils.SetActive(self.FinishBlack, isPass or not isUnlock)

    CfUtils.SetUISwitchImage(self.ImgLineUP, self._isChallenge and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgLineDOWN, self._isChallenge and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgFinish2, self._isChallenge and 2 or 1)
    CfUtils.SetUISwitchText(self.TxtCheckpoint, not isUnlock and 3  or (self._isChallenge and 2 or 1))
    CfUtils.SetUISwitchImage(self.BigSelect.transform:Find("CornerGroup/ImgCorner1"), self._isChallenge and 2 or 1)
    CfUtils.SetUISwitchImage(self.BigSelect.transform:Find("CornerGroup/ImgCorner2"), self._isChallenge and 2 or 1)
    CfUtils.SetUISwitchImage(self.BigSelect.transform:Find("CornerGroup/ImgCorner3"), self._isChallenge and 2 or 1)
    CfUtils.SetUISwitchImage(self.BigSelect.transform:Find("CornerGroup/ImgCorner4"), self._isChallenge and 2 or 1)

    CfUtils.SetActive(self.DecorateDot, not isUnlock)

    local isBoss = (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss)
    local isStory = checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Story

    CfUtils.SetActive(self.Item1.transform:Find("UIFX_MainChapterDialogBtnBubbleGroupSelectEffectBoss"), isBoss)
    --CfUtils.SetUISwitchImage(self.ImgLabel, isBoss and 1 or 2)

    ---困难没有星级了

    CfUtils.SetActive(self.Finish, isPass)

    if self._isChallenge then
        self:FillChallenge()
        --local isComplete = QuestConfMgr:GetInstance():IsCompleteAllCondition(self._curQuestId)
        --KTool.SetActive(self.Finish.transform:Find("ImgFinish"), isComplete)
    else
        CfUtils.SetActive(self.Item2, checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Battle)
        CfUtils.SetActive(self.SmallNormal.transform:Find("Item3"), (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Task))
        --CfUtils.SetActive(self.ImgLabel, not (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Battle))
        CfUtils.SetActive(self.Item1, (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Story) or (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.All) or (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.StoryTask))
        self:FillCommon()
        --KTool.SetActive(self.Finish.transform:Find("ImgFinish"), isPass)
    end

end

function UIMainChapterQuestNode:FillCommon()
    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curQuestId)
    local isShowFightImage = true
    --纯剧情
    if (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Story) then
        CfUtils.SetActive(self.Item1.transform:Find("Mask/ImgRole"), true)
        CfUtils.SetActive(self.ImgRole, true)
        isShowFightImage = false

        CfUtils.FillImage(self.Item1.transform:Find("Mask/ImgRole"), plotVo.listImageS)
        CfUtils.FillImage(self.ImgRole, plotVo.listImageB)
    elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Task) or (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.StoryTask) then
        CfUtils.SetActive(self.Item1.transform:Find("Mask/ImgRole"), true)
        CfUtils.SetActive(self.ImgRole, true)
        isShowFightImage = false

        CfUtils.FillImage(self.Item1.transform:Find("Mask/ImgRole"), plotVo.listImageS)
        CfUtils.FillImage(self.ImgRole, plotVo.listImageB)
    --剧情加战斗
    elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.All) and (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Creep) then
        CfUtils.SetActive(self.Item1.transform:Find("Mask/ImgRole"), true)
        CfUtils.SetActive(self.ImgRole, true)

        CfUtils.FillImage(self.Item1.transform:Find("Mask/ImgRole"), plotVo.listImageS)
        CfUtils.FillImage(self.ImgRole, plotVo.listImageB)
    --有boss
    elseif (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss) then
        CfUtils.SetActive(self.Item1.transform:Find("Mask/ImgRole"), true)
        CfUtils.SetActive(self.ImgRole, true)

        CfUtils.FillImage(self.Item1.transform:Find("Mask/ImgRole"), plotVo.listImageS)
        CfUtils.FillImage(self.ImgRole, plotVo.listImageB)
    --纯战斗
    elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Battle) then
        CfUtils.SetActive(self.ImgMonster, true)
        CfUtils.FillImage(self.ImgMonster, plotVo.listImageS)
    end 
    CfUtils.SetActive(self.Item1.transform:Find("ImgFight"), isShowFightImage)
    CfUtils.SetActive(self.ImgFight, isShowFightImage)
end

