function UIMainChapterQuestNode:RefreshSelectActive(isSelect)
    if isSelect then
        CfUtils.PlayAnimator(self.controller.gameObject, "In")
    else
        CfUtils.PlayAnimator(self.controller.gameObject, "Out")
    end

    self:FillOther(isSelect)
end

function UIMainChapterQuestNode:FillOther(isSelect)
    if self._isChallenge then
        local isBoss = (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss)
        CfUtils.SetActive(self.ImgLabel, isBoss)
        if isBoss then
            CfUtils.SetUISwitchImage(self.ImgLabel, 1)
        end
    else
        if isSelect then
            local isShow = false
            if (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Story) then
                isShow = false
            --剧情加战斗
            elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.All) and (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Creep) then
                isShow = false
            --有boss
            elseif (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss) then
                isShow = true
            --纯战斗
            elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Battle) or (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.StoryTask) then
                isShow = true
            end 
            CfUtils.SetActive(self.ImgLabel, isShow)

            if checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.StoryTask then
                CfUtils.SetUISwitchImage(self.ImgLabel, 3)
            else
                local isBoss = (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss)
                CfUtils.SetUISwitchImage(self.ImgLabel, (isBoss and 1 or 2))
            end
        else
            local isShow = false
            if (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Story) then
                isShow = false
            --剧情加战斗
            elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.All) and (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Creep) then
                isShow = false
            --有boss
            elseif (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss) then
                isShow = true
            --纯战斗
            elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.Battle) then
                isShow = false
            elseif (checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.StoryTask) then
                isShow = true
            end 

            CfUtils.SetActive(self.ImgLabel, isShow)
            if checkNumber(self._curQuestVo.type) == Constants.QuestBattleType.StoryTask then
                CfUtils.SetUISwitchImage(self.ImgLabel, 3)
            else
                local isBoss = (checkNumber(self._curQuestVo.monsteType) == Constants.RoleClass.Boss)
                CfUtils.SetUISwitchImage(self.ImgLabel, (isBoss and 1 or 2))
            end
        end
    end
end

function UIMainChapterQuestNode:PlayFinishAni()
    CfUtils.PlayAnimator(self.Finish, "Finish")
end

function UIMainChapterQuestNode:OnBtnQuest()
    if self._cb then
        self._cb(self._curQuestVo)
    end
end

function UIMainChapterQuestNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainChapterQuestNode